function challengeHistory(){const key=currentFranchiseKey();return history.filter(b=>betBelongsToCurrentFranchise(b)&&(!b.franchiseKey||b.franchiseKey===key));}
function challengeWeekKey(d=new Date()){const x=new Date(d);const day=x.getDay();const diff=day===0?-6:1-day;x.setDate(x.getDate()+diff);return x.toLocaleDateString('en-CA')}
function challengeHistoryWeek(){const key=currentFranchiseKey();const wk=challengeWeekKey();return challengeHistory().filter(b=>{const stamp=b.placedAt||b.settledAt;if(!stamp)return false;return challengeWeekKey(new Date(stamp))===wk;});}
function challengeProgress(ch,scope){const bets=scope==='weekly'?challengeHistoryWeek():challengeHistory();if(ch.metric==='settled')return bets.filter(b=>['won','lost','void'].includes(b.status)).length;if(ch.metric==='parlays')return bets.filter(b=>(b.legs||[]).length>=4).length;if(ch.metric==='wins')return bets.filter(b=>b.status==='won').length;if(ch.metric==='parlayWins')return bets.filter(b=>b.status==='won'&&(b.legs||[]).length>1).length;if(ch.metric==='longshotWins')return bets.filter(b=>b.status==='won'&&Number(b.americanOdds)>0&&Number(b.americanOdds)>=200).length;if(ch.metric==='sharp'){const settled=bets.filter(b=>['won','lost'].includes(b.status));return settled.length;}return 0}
function evaluateChallenges(){if(!franchiseLoaded)return false;economyEnsureToday();let changed=false;const wk=challengeWeekKey();if(economy.challengeWeek!==wk){economy.challengeWeek=wk;economy.weeklyChallengeClaimed={};changed=true;}if(!economy.weeklyChallengeClaimed||typeof economy.weeklyChallengeClaimed!=='object'){economy.weeklyChallengeClaimed={};changed=true}if(!economy.franchiseChallengeClaimed||typeof economy.franchiseChallengeClaimed!=='object'){economy.franchiseChallengeClaimed={};changed=true}if(changed)saveWallet();return changed}
function claimChallenge(scope,id){if(!franchiseLoaded){setStatus('Import a Franchise save before claiming challenge rewards.','err');return}economyEnsureToday();evaluateChallenges();const list=scope==='weekly'?weeklyChallenges:franchiseChallenges;const ch=list.find(x=>x.id===id);if(!ch)return;const progress=Math.min(ch.target,challengeProgress(ch,scope));const key=scope==='weekly'?'weeklyChallengeClaimed':'franchiseChallengeClaimed';if(economy[key]?.[ch.id]){setStatus('That challenge reward has already been claimed.','err');return}let eligible=progress>=ch.target;if(ch.metric==='sharp'){const settled=challengeHistory().filter(b=>['won','lost'].includes(b.status));const wins=settled.filter(b=>b.status==='won').length;eligible=settled.length>=ch.target&&wins/settled.length>=0.65}if(!eligible){setStatus('Challenge is not complete yet.','err');return}if(!economy[key])economy[key]={};economy[key][ch.id]=true;balance+=ch.reward;saveWallet();renderBalance();renderChallenges();setStatus(`${ch.title} reward claimed! +${money(ch.reward)}.`,'ok')}

function economyEnsureToday(){const d=todayKey();if(economy.date!==d){const oldWeekly=economy.weeklyChallengeClaimed||{};const oldFranchise=economy.franchiseChallengeClaimed||{};economy={date:d,checkIn:false,triviaIds:[],answers:{},perfectPaid:false,filmClicks:0,lastFilmClick:0,triviaVersion:4,challengeVersion:2,challengeWeek:challengeWeekKey(),weeklyChallengeClaimed:oldWeekly,franchiseChallengeClaimed:oldFranchise};}if(economy.triviaVersion!==4){economy.triviaVersion=4;economy.triviaIds=[];economy.answers={};economy.perfectPaid=false;}if(economy.challengeVersion!==2){economy.challengeVersion=2;economy.challengeWeek=challengeWeekKey();economy.weeklyChallengeClaimed={};economy.franchiseChallengeClaimed=economy.franchiseChallengeClaimed||{};}if(!economy.weeklyChallengeClaimed||typeof economy.weeklyChallengeClaimed!=='object')economy.weeklyChallengeClaimed={};if(!economy.franchiseChallengeClaimed||typeof economy.franchiseChallengeClaimed!=='object')economy.franchiseChallengeClaimed={};if(!Array.isArray(economy.triviaIds)||economy.triviaIds.length!==5){economy.triviaIds=pickDailyTrivia();economy.answers={};economy.perfectPaid=false;}return economy}
function economyEarn(amount,reason){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}balance+=Number(amount)||0;saveWallet();setStatus(`${reason} +${money(amount)}.`,'ok');renderEconomy();}
function claimDailyCheckIn(){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();if(economy.checkIn){setStatus('Daily check-in already claimed. Come back tomorrow.','err');return}economy.checkIn=true;economyEarn(25,'Daily check-in');}
function answerTrivia(id,choice){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();if(economy.answers[id]!==undefined)return;const q=triviaBank.find(x=>x.id===id);if(!q)return;const correct=Number(choice)===q.a;economy.answers[id]={choice:Number(choice),correct};if(correct)balance+=20;const allDone=economy.triviaIds.every(x=>economy.answers[x]);if(allDone&&Object.values(economy.answers).filter(x=>x.correct).length===5&&!economy.perfectPaid){economy.perfectPaid=true;balance+=40;}saveWallet();renderEconomy();setStatus(correct?'Correct! +$20.':'Not quite — no reward this time.',correct?'ok':'err');}
function filmRoom(){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();const now=Date.now();const wait=30000-(now-Number(economy.lastFilmClick||0));if(economy.filmClicks>=10){setStatus('Daily Film Room limit reached. Come back tomorrow.','err');return}if(wait>0){setStatus(`Film Room is on cooldown for ${Math.ceil(wait/1000)}s.`,'err');return}economy.filmClicks++;economy.lastFilmClick=now;economyEarn(5,'Film Room');}
function msUntilTomorrow(){const d=new Date();const next=new Date(d);next.setHours(24,0,0,0);return Math.max(0,next-d)}
function formatCountdown(ms){let total=Math.max(0,Math.ceil(ms/1000));const h=Math.floor(total/3600);total%=3600;const m=Math.floor(total/60);const sec=total%60;return h>0?`${h}h ${String(m).padStart(2,'0')}m ${String(sec).padStart(2,'0')}s`:`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function renderEconomy(){const c=document.getElementById('economyContent');if(!c)return;economyEnsureToday();evaluateChallenges();const qs=economy.triviaIds.map(id=>triviaBank.find(q=>q.id===id)).filter(Boolean);const answered=qs.filter(q=>economy.answers[q.id]).length;const correct=qs.filter(q=>economy.answers[q.id]?.correct).length;const filmLeft=Math.max(0,10-Number(economy.filmClicks||0));const wait=Math.max(0,30000-(Date.now()-Number(economy.lastFilmClick||0)));const tomorrow=formatCountdown(msUntilTomorrow());const triviaDone=answered===5;const checkDone=!!economy.checkIn;const filmDone=filmLeft===0;const filmLocked=filmDone||wait>0;const checkStatus=checkDone?`<div class="economy-status"><span>AVAILABLE TOMORROW</span><span class="countdown">${tomorrow}</span></div>`:'';const filmStatus=filmDone?`<div class="economy-status"><span>DAILY LIMIT REACHED</span><span class="countdown">${tomorrow}</span></div>`:wait>0?`<div class="economy-status"><span>NEXT REVIEW IN</span><span class="countdown">${formatCountdown(wait)}</span></div>`:'';const triviaContent=triviaDone?`<div class="trivia-complete"><div class="eyebrow">NFL IQ COMPLETE</div><div class="trivia-countdown">${tomorrow}</div><div class="economy-muted">Trivia available again tomorrow.</div></div>`:`<div class="trivia-list">${qs.map(q=>{const ans=economy.answers[q.id];return `<div class="trivia-card"><div class="trivia-q">${q.q}</div><div class="trivia-options">${q.o.map((opt,i)=>`<button ${ans?'disabled':''} class="${ans?(i===q.a?'correct':i===ans.choice?'wrong':''):''}" data-trivia="${q.id}" data-choice="${i}">${String.fromCharCode(65+i)}. ${opt}</button>`).join('')}</div>${ans?`<div class="trivia-result ${ans.correct?'ok':'err'}">${ans.correct?'Correct — +$20':'Incorrect — the correct answer was '+q.o[q.a]}</div>${q.e?`<div class="economy-muted trivia-explanation">${q.e}</div>`:''}`:''}</div>`}).join('')}</div>`;c.innerHTML=`<div class="economy-grid"><article class="economy-card"><div class="eyebrow">BANKROLL</div><h3>Economy snapshot</h3><div class="economy-reward">${money(balance)}</div><div class="economy-stat"><span>Trivia correct</span><b>${correct}/${answered||0}</b></div><div class="economy-stat"><span>Film reviews</span><b>${economy.filmClicks}/10</b></div><div class="economy-stat"><span>Daily check-in</span><b>${checkDone?'COMPLETE':'AVAILABLE'}</b></div></article><article class="economy-card"><div class="eyebrow">DAILY CHECK-IN</div><h3>Open the books</h3><div class="economy-reward">+$25</div><div class="economy-muted">One claim per day. Small guaranteed bankroll boost without making betting irrelevant.</div>${checkDone?checkStatus:'<button class="btn primary economy-btn" id="checkInBtn">CLAIM $25</button>'}</article><article class="economy-card"><div class="eyebrow">FILM ROOM</div><h3>Review game film</h3><div class="economy-reward">+$5</div><div class="economy-muted">10 reviews per day, with a 30-second cooldown between reviews. ${filmLeft} reviews remaining.</div><div class="economy-progress"><span style="width:${(Number(economy.filmClicks||0)/10)*100}%"></span></div>${filmLocked?filmStatus:`<button class="btn primary economy-btn" id="filmBtn">REVIEW FILM +$5</button>`}</article></div><article class="economy-card"><div class="eyebrow">NFL IQ</div><h3>Daily Madden / NFL Trivia</h3><div class="economy-muted">5 questions per day with a tougher mix: 2 hard, 2 medium, 1 easy. Correct answer: +$20. Perfect 5/5 bonus: +$40. Wrong answers do not cost anything.</div><div class="economy-progress"><span style="width:${(answered/5)*100}%"></span></div>${triviaContent}</article>`;c.querySelector('#checkInBtn')?.addEventListener('click',claimDailyCheckIn);c.querySelector('#filmBtn')?.addEventListener('click',filmRoom);c.querySelectorAll('[data-trivia]').forEach(b=>b.addEventListener('click',()=>answerTrivia(b.dataset.trivia,Number(b.dataset.choice))));}

function setStatus(t,c=''){const e=document.getElementById('status');e.textContent=t;e.className='status '+c}
function renderChallenges(){const c=document.getElementById('challengesContent');if(!c)return;if(!franchiseLoaded){c.innerHTML='<article class="economy-card"><div class="eyebrow">CHALLENGES</div><h3>Import a franchise to begin</h3><div class="economy-muted">Challenge progress and rewards are tied to the currently loaded franchise.</div></article>';return}economyEnsureToday();evaluateChallenges();const renderChallengeCards=(list,scope)=>list.map(ch=>{const progress=Math.min(ch.target,challengeProgress(ch,scope));const claimed=scope==='weekly'?!!economy.weeklyChallengeClaimed?.[ch.id]:!!economy.franchiseChallengeClaimed?.[ch.id];let complete=progress>=ch.target; if(ch.metric==='sharp'){const settled=challengeHistory().filter(b=>['won','lost'].includes(b.status));const wins=settled.filter(b=>b.status==='won').length;complete=settled.length>=ch.target&&wins/settled.length>=0.65}return `<article class="challenge-card ${claimed?'done':''}"><div class="challenge-head"><div><div class="challenge-title">${ch.title}</div><div class="challenge-desc">${ch.desc}</div></div><div class="challenge-reward">+$${ch.reward}</div></div><div class="challenge-progress"><span style="width:${complete||claimed?100:Math.min(100,(progress/ch.target)*100)}%"></span></div><div class="challenge-foot"><span>${claimed?'COMPLETED':`${progress}/${ch.target}`}</span><span>${claimed?'REWARD CLAIMED':scope==='weekly'?'THIS WEEK':'FRANCHISE'}</span></div>${complete&&!claimed?`<button class="challenge-claim" data-claim-scope="${scope}" data-claim-id="${ch.id}">CLAIM REWARD +${money(ch.reward)}</button>`:''}</article>`}).join('');const weeklyChallengeHtml=renderChallengeCards(weeklyChallenges,'weekly');const franchiseChallengeHtml=renderChallengeCards(franchiseChallenges,'franchise');c.innerHTML=`<article class="economy-card"><div class="eyebrow">WEEKLY CHALLENGES</div><h3>Beat the board</h3><div class="economy-muted">Three harder challenges reset every Monday. Complete them during the current week, then claim each reward.</div><div class="challenge-grid">${weeklyChallengeHtml}</div></article><article class="economy-card"><div class="eyebrow">FRANCHISE CHALLENGES</div><h3>Build your sportsbook legacy</h3><div class="economy-muted">Long-term challenges persist for this franchise from start to finish. These are intentionally harder milestones with larger rewards.</div><div class="challenge-grid">${franchiseChallengeHtml}</div></article>`;c.querySelectorAll('[data-claim-scope]').forEach(b=>b.addEventListener('click',()=>claimChallenge(b.dataset.claimScope,b.dataset.claimId)));}

function socialUpcomingGames(){
  const phaseOrder={preseason:0,regular:1,playoffs:2,superbowl:3};
  return (games||[]).filter(g=>!isPlayed(g)).sort((a,b)=>{
    const pa=phaseOrder[String(a.phase||'regular')]??9,pb=phaseOrder[String(b.phase||'regular')]??9;
    if(pa!==pb)return pa-pb;
    const wa=Number(a.phaseWeek??a.week??a.SeasonWeek),wb=Number(b.phaseWeek??b.week??b.SeasonWeek);
    if(Number.isFinite(wa)&&Number.isFinite(wb)&&wa!==wb)return wa-wb;
    return gameSort(a,b);
  });
}
function propPlayerSide(p,g){
  const pi=(p.teamIndex!==null&&p.teamIndex!==undefined)?String(p.teamIndex):null;
  const ai=(g.awayTeamResolved?.TeamIndex!==null&&g.awayTeamResolved?.TeamIndex!==undefined)?String(g.awayTeamResolved.TeamIndex):null;
  const hi=(g.homeTeamResolved?.TeamIndex!==null&&g.homeTeamResolved?.TeamIndex!==undefined)?String(g.homeTeamResolved.TeamIndex):null;
  if(pi!==null&&ai!==null&&pi===ai)return 'AWAY';
  if(pi!==null&&hi!==null&&pi===hi)return 'HOME';
  if(p.teamName&&p.teamName===g.awayName)return 'AWAY';
  if(p.teamName&&p.teamName===g.homeName)return 'HOME';
  return null;
}
function socialMarkets(){
  const props=currentData?.playerProps||[];
  const upcoming=socialUpcomingGames();
  const out=[];
  // playerProps are franchise-level markets. They represent the player's next
  // matchup, so attach each player to only the FIRST upcoming game for that team.
  // This prevents the same player's markets from being duplicated across every
  // remaining game on the schedule.
  const nextGameByTeam=new Map();
  for(const g of upcoming){
    for(const team of [g.awayTeamResolved?.TeamIndex,g.homeTeamResolved?.TeamIndex,g.awayName,g.homeName]){
      if(team===null||team===undefined||team==='')continue;
      const key=String(team);
      if(!nextGameByTeam.has(key))nextGameByTeam.set(key,g);
    }
  }
  for(const p of props){
    let g=null,side=null;
    if(p.teamIndex!==null&&p.teamIndex!==undefined){
      g=nextGameByTeam.get(String(p.teamIndex))||null;
      if(g)side=propPlayerSide(p,g);
    }
    if(!g&&(p.teamName||p.team)){const teamName=String(p.teamName||p.team);g=nextGameByTeam.get(teamName)||null;if(g)side=propPlayerSide(p,g)}
    if(!g||!side)continue;
    for(const m of (p.markets||[p])){
      if(!Number.isFinite(Number(m.line)))continue;
      const avg=Number(m.average); const hasAverage=Number.isFinite(avg);
      const line=Number(m.line);
      const edge=hasAverage?avg-line:0;
      const over=hasAverage?edge>=0:true;
      const pct=hasAverage?Math.min(92,Math.max(55,Math.round(64+Math.abs(edge)*0.9))):58;
      const odds=propOdds(m,over?'over':'under');
      const source=m.source||p.source||'historical';
      const label=`${p.name} ${over?'O':'U'} ${line} ${m.label}`;
      out.push({g,p,m,side,edge,over,odds,pct,hasAverage,source,label,market:m.label,selection:{label,market:m.label,display:`${over?'O':'U'} ${line} ${fmtOdds(odds)}`,odds,gameId:gameKey(g),gameIndex:g.index,week:g.week,phase:g.phase,phaseWeek:g.phaseWeek,away:g.awayName,home:g.homeName,kind:over?'propOver':'propUnder',line,playerId:m.playerId||p.playerId,propStat:m.stat}});
    }
  }
  return out.sort((a,b)=>(Number(b.hasAverage)-Number(a.hasAverage))||b.pct-a.pct);
}
function socialDiverseMarkets(limit=6){
  const all=socialMarkets();
  const out=[]; const seenPlayers=new Set(); const seenMarkets=new Set();
  // Prefer one market per player first so Social doesn't become a feed of one star.
  for(const x of all){
    const id=String(x.p.playerId||x.p.name||'');
    if(seenPlayers.has(id))continue;
    out.push(x);seenPlayers.add(id);
    if(out.length>=limit)return out;
  }
  // If fewer players have usable markets, fill the remaining slots with the best
  // markets while avoiding exact duplicate player/market combinations.
  for(const x of all){
    if(out.length>=limit)break;
    const key=`${String(x.p.playerId||x.p.name||'')}|${String(x.m.stat||x.m.label||'')}`;
    if(seenMarkets.has(key))continue;
    seenMarkets.add(key);
    if(!out.includes(x))out.push(x);
  }
  return out;
}
function socialPayload(value){return encodeURIComponent(JSON.stringify(value)).replace(/'/g,'%27')}
function socialAdd(selection){const x={...selection,key:crypto.randomUUID()};slip.push(x);saveState();renderSlip();setStatus('AI selection added to bet slip.','ok')}
function socialAddParlay(legs){for(const l of legs)slip.push({...l,key:crypto.randomUUID()});saveState();renderSlip();setStatus('Suggested parlay added to bet slip.','ok')}
function socialPickCard(x){const direction=x.over?'OVER':'UNDER';const avg=Number(x.m.average);const line=Number(x.m.line);const reason=x.hasAverage?`Franchise sample average is ${avg.toFixed(1)} against a ${line.toFixed(1)} line, a ${Math.abs(avg-line).toFixed(1)}-unit gap. The model favors the ${direction} side.`:`No historical sample is available yet. This is a roster-based projection line; treat the ${direction} side as a light model lean, not a historical trend.`;const sourceLabel=x.hasAverage?'HISTORICAL':'ROSTER PROJECTION';return `<article class="social-pick"><div class="social-pick-head"><div><div class="social-pick-name">${escapeHtml(x.p.name)} <span class="prop-role">${escapeHtml(x.p.role||'')}</span></div><div class="social-pick-meta">${escapeHtml(x.p.team||x.p.teamName||'')} • ${escapeHtml(x.m.label)} • ${escapeHtml(x.g.awayName)} @ ${escapeHtml(x.g.homeName)}</div></div><span class="social-confidence">${x.pct}% MODEL CONFIDENCE</span></div><div style="margin-top:8px;font-weight:900">${direction} ${line} <span class="betmeta">${fmtOdds(x.odds)}</span></div><div class="social-pick-reason">${reason}</div><div class="social-pick-actions"><button class="btn primary" data-social-add='${socialPayload(x.selection)}'>ADD TO SLIP</button><span class="social-badge">${sourceLabel}</span></div></article>`}
function renderSocialPage(p){
  const container=document.getElementById(p+'Content'); if(!container)return; if(!franchiseLoaded){container.innerHTML='<div class="empty">Import a franchise first to generate Social content.</div>';return}
  const picks=socialMarkets();
  const top=socialDiverseMarkets(6);
  if(p==='aiPicks'){container.innerHTML=`<div class="social-grid"><article class="social-card social-single"><div class="eyebrow">TOP AI LEANS</div><h3>Data-backed suggestions</h3>${top.length?top.map(socialPickCard).join(''):'<div class="empty">Not enough player-prop data to generate picks.</div>'}</article></div>`}
  else if(p==='suggested'){
    const sets=[]; if(top.length>=2)sets.push({name:'AI SAFE PARLAY',desc:'Two stronger model leans with a lower leg count.',legs:top.slice(0,2)}); if(top.length>=3)sets.push({name:'AI 3-LEG PARLAY',desc:'Balanced three-leg combination.',legs:top.slice(0,3)}); if(top.length>=5)sets.push({name:'AI LONGSHOT',desc:'Five-leg higher-risk combination for a bigger return.',legs:top.slice(0,5)});
    container.innerHTML=`<div class="social-grid">${sets.map(set=>{const dec=set.legs.reduce((v,x)=>v*americanToDecimal(x.odds),1);const am=decimalToAmerican(Math.min(dec,1+parlayMaxAmerican(set.legs.length)/100));return `<article class="social-card"><div class="eyebrow">${set.name}</div><h3>${set.desc}</h3>${set.legs.map(l=>`<div class="social-leg"><span>${escapeHtml(l.label)}</span><b>${fmtOdds(l.odds)}</b></div>`).join('')}<div class="row"><span>Combined odds</span><b>${am}</b></div><div class="social-actions"><button class="btn primary" data-social-parlay='${socialPayload(set.legs.map(x=>x.selection))}'>ADD ALL TO SLIP</button></div></article>`}).join('')||'<div class="empty">Not enough prop data for suggested parlays.</div>'}</div>`
  } else if(p==='forum'){
    const posts=top.slice(0,5).map((x,i)=>{const authors=['GridironGuru','StatHead','SafeBetSam','LongshotLarry','The Sharp'];const comments=[`I like ${x.label}. The current franchise sample gives the ${x.over?'over':'under'} some room against the line.`,`Worth watching: ${x.p.name} has a ${Number(x.m.average).toFixed(1)} average in this market sample.`,`I'm keeping this one on the safer side — ${x.label}.`,`This is the kind of leg I'd use when building a longshot.`,`Model agrees with the ${x.over?'over':'under'} here, but the edge is not a guarantee.`];return `<div class="forum-post"><div class="forum-author">${authors[i]} • ${x.pct}% model lean</div><div class="forum-text">${escapeHtml(comments[i])}</div><button class="btn" style="margin-top:8px" data-social-add='${socialPayload(x.selection)}'>ADD THIS BET</button></div>`}).join('');container.innerHTML=`<article class="social-card"><div class="eyebrow">COMMUNITY FEED</div><h3>What the sportsbook crowd is talking about</h3><div class="social-forum">${posts||'<div class="empty">No franchise markets available yet.</div>'}</div><div class="social-disclaimer">Community posts are simulated for this offline franchise sportsbook and are generated from available data.</div></article>`
  } else if(p==='trending'){
    const rows=top.map((x,i)=>`<tr><td><b>#${i+1}</b></td><td>${escapeHtml(x.label)}</td><td>${x.pct}%</td><td>${fmtOdds(x.odds)}</td><td><button class="btn" data-social-add='${socialPayload(x.selection)}'>ADD</button></td></tr>`).join('');container.innerHTML=`<article class="social-card"><div class="eyebrow">TRENDING</div><h3>Popular-looking markets</h3><table class="social-table"><tbody>${rows||'<tr><td colspan="5">No markets available.</td></tr>'}</tbody></table></article>`
  } else if(p==='insights'){
    const rows=top.slice(0,8).map(x=>{const avg=Number(x.m.average);const detail=x.hasAverage?`sample average ${avg.toFixed(1)} • line ${Number(x.m.line).toFixed(1)}`:`roster projection • line ${Number(x.m.line).toFixed(1)}`;const reason=x.hasAverage?`The current line is ${Math.abs(avg-Number(x.m.line)).toFixed(1)} away from the franchise sample average. That creates a ${x.over?'positive over':'positive under'} model lean.`:`There is not enough historical game data yet, so this market is projected from the current roster rather than past performance.`;return `<article class="social-pick"><div class="social-pick-name">${escapeHtml(x.p.name)} • ${escapeHtml(x.m.label)}</div><div class="social-pick-meta">${escapeHtml(x.p.team||x.p.teamName||'')} • ${detail} • ${escapeHtml(x.g.awayName)} @ ${escapeHtml(x.g.homeName)}</div><div class="social-pick-reason">${reason}</div></article>`}).join('');container.innerHTML=`<article class="social-card"><div class="eyebrow">STAT INSIGHTS</div><h3>Numbers behind the markets</h3>${rows||'<div class="empty">No player-prop sample available.</div>'}</article>`
  } else if(p==='leaderboard'){
    const bets=history.filter(b=>betBelongsToCurrentFranchise(b));const settled=bets.filter(b=>['won','lost'].includes(b.status));const wins=settled.filter(b=>b.status==='won').length;const profit=settled.reduce((n,b)=>n+Number(b.profit||0),0);const rows=[['You',settled.length,profit,true],['GridironGuru',Math.max(8,settled.length-2),Math.max(0,profit*0.72+350),false],['StatHead',Math.max(6,settled.length-5),Math.max(0,profit*0.48+210),false],['LongshotLarry',Math.max(5,settled.length-7),Math.max(0,profit*0.32+125),false]].sort((a,b)=>(b[2]-a[2])||(b[1]-a[1])||String(a[0]).localeCompare(String(b[0])));container.innerHTML=`<article class="social-card"><div class="eyebrow">COMMUNITY LEADERBOARD</div><h3>Franchise sportsbook standings</h3><table class="social-table"><tbody>${rows.map((r,i)=>`<tr><td><b>#${i+1}</b></td><td>${r[0]}${r[3]?' <span class="social-badge">YOU</span>':''}</td><td>${r[1]} settled</td><td class="${r[2]>=0?'pos':'neg'}">${money(r[2])}</td></tr>`).join('')}</tbody></table><div class="social-disclaimer">Community profiles are simulated. Rankings are sorted by net profit, with settled bets used as the tiebreaker.</div></article>`}
  container.querySelectorAll('[data-social-add]').forEach(b=>b.addEventListener('click',()=>socialAdd(JSON.parse(decodeURIComponent(b.dataset.socialAdd)))));container.querySelectorAll('[data-social-parlay]').forEach(b=>b.addEventListener('click',()=>socialAddParlay(JSON.parse(decodeURIComponent(b.dataset.socialParlay)))));
}

const NAV_GROUPS_KEY='m27-nav-groups';
const NAV_PAGE_GROUP={games:'sportsbook',props:'sportsbook',active:'sportsbook',history:'sportsbook',standings:'sportsbook',forum:'social',aiPicks:'social',suggested:'social',trending:'social',insights:'social',leaderboard:'social',economy:'account',challenges:'account',stats:'account',settings:'account'};
function loadNavGroups(){let state=null;try{state=JSON.parse(localStorage.getItem(NAV_GROUPS_KEY)||'null')}catch{};const defaults={sportsbook:true,social:true,account:true};const merged={...defaults,...(state&&typeof state==='object'?state:{})};document.querySelectorAll('[data-nav-group]').forEach(g=>{const key=g.dataset.navGroup;setNavGroup(key,merged[key]!==false)});}
function saveNavGroups(){const state={};document.querySelectorAll('[data-nav-group]').forEach(g=>{state[g.dataset.navGroup]=!g.classList.contains('collapsed')});try{localStorage.setItem(NAV_GROUPS_KEY,JSON.stringify(state))}catch{}}
function setNavGroup(key,expanded){const g=document.querySelector(`[data-nav-group="${key}"]`);if(!g)return;g.classList.toggle('collapsed',!expanded);const b=g.querySelector('[data-nav-toggle]');if(b)b.setAttribute('aria-expanded',expanded?'true':'false')}
function toggleNavGroup(key){const g=document.querySelector(`[data-nav-group="${key}"]`);if(!g)return;setNavGroup(key,g.classList.contains('collapsed'));saveNavGroups()}
function showPage(p){activePage=p;const group=NAV_PAGE_GROUP[p];if(group)setNavGroup(group,true);document.querySelectorAll('.nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p+'Page').classList.add('active');if(p==='games')renderGames();if(p==='standings')renderStandings();if(p==='active')renderActiveBets();if(p==='history')renderHistory();if(p==='stats')renderStats();if(p==='props')renderProps();if(p==='economy')renderEconomy();if(p==='challenges')renderChallenges();if(['forum','aiPicks','suggested','trending','insights','leaderboard'].includes(p))renderSocialPage(p)}
function phaseLabel(phase){return phase==='preseason'?'Preseason':phase==='playoffs'?'Playoffs':phase==='superbowl'?'Super Bowl':'Regular Season'}
function setPhaseOptions(phaseWeeks){document.querySelectorAll('#phasebar [data-phase]').forEach(b=>{const phase=b.dataset.phase;const count=(phaseWeeks[phase]||[]).length;b.style.display=count?'inline-block':'none';b.title=count?`${count} week${count===1?'':'s'} available`:'No games loaded for this phase';});}
function populatePhaseWeeks(phase,preferred){const weeks=(currentData?.summary?.phaseWeeks?.[phase]||[]).map(Number).filter(Number.isFinite);const sel=document.getElementById('week');sel.innerHTML=weeks.map(w=>`<option value="${w}">${w}</option>`).join('');let pick=Number(preferred);if(!weeks.includes(pick))pick=weeks[0]??1;sel.value=String(pick);document.getElementById('weekLabel').textContent=phaseLabel(phase)+' Week';document.getElementById('title').textContent=`${phaseLabel(phase)} • Week ${pick}`;document.querySelectorAll('#phasebar [data-phase]').forEach(x=>x.classList.toggle('active',x.dataset.phase===phase));}
async function loadResult(result){document.getElementById('modalText').textContent=JSON.stringify(result,null,2);if(!result.ok){document.getElementById('startupStatus').textContent='Import failed. Choose another Franchise save.';document.getElementById('startupStatus').className='startup-status err';setStatus('Parser error. See Import / Refresh Result.','err');document.getElementById('modal').classList.add('show');return}franchiseLoaded=true;currentData=result;activateWallet(currentFranchiseKey());games=(result.games||[]).map(g=>{const at=g.awayTeamResolved||{},ht=g.homeTeamResolved||{};return{...g,week:Number(g.SeasonWeek),awayName:teamName(at),homeName:teamName(ht),awayAb:teamAb(at),homeAb:teamAb(ht)}});teams=result.teams||[];document.getElementById('dataTag').textContent='LIVE SAVE';document.getElementById('franchiseName').textContent=result.fileName+' • Madden '+result.gameYear+' • '+result.summary.playableGames+' games imported';setPhaseOptions(result.summary.phaseWeeks||{});const current=Number.isFinite(Number(result.summary.activeSeasonWeek))?Number(result.summary.activeSeasonWeek)+1:1;window.selectedPhase=(result.summary.phaseWeeks?.regular||[]).includes(current)?'regular':(Object.keys(result.summary.phaseWeeks||{}).find(k=>(result.summary.phaseWeeks[k]||[]).length)||'regular');populatePhaseWeeks(window.selectedPhase,current);document.getElementById('title').textContent=`${phaseLabel(window.selectedPhase)} • Week ${Number(document.getElementById('week').value)||1}`;settlePending();reconcileLegacyVoids();renderGames();renderStandings();renderActiveBets();renderHistory();renderStats();renderProps();renderBalance();document.body.classList.remove('startup-locked');document.getElementById('startupGate').classList.add('hidden');setStatus(`Franchise loaded. Active Madden Week ${current+1}. Lines are generated from Franchise data.`,'ok')}
async function importFranchiseFromPicker(){try{document.getElementById('startupStatus').textContent='Parsing Franchise save…';document.getElementById('startupStatus').className='startup-status';setStatus('Parsing Franchise…');const p=await window.maddenAPI.pickFranchise();if(!p||p.canceled){document.getElementById('startupStatus').textContent='Waiting for a Franchise save…';return}const r=await window.maddenAPI.parseFranchise(p.path);await loadResult(r)}catch(e){document.getElementById('startupStatus').textContent='Import error: '+e.message;document.getElementById('startupStatus').className='startup-status err';setStatus('Import error: '+e.message,'err')}}
document.getElementById('importBtn').addEventListener('click',importFranchiseFromPicker);document.getElementById('startupImportBtn').addEventListener('click',importFranchiseFromPicker);
document.getElementById('refreshBtn').addEventListener('click',async()=>{try{if(!franchiseLoaded){setStatus('Import a Franchise first.','err');return}setStatus('Refreshing saved Franchise…');const r=await window.maddenAPI.reparseFranchise();await loadResult(r);setStatus('Save refreshed. Any completed pending bets were settled.','ok')}catch(e){setStatus('Refresh error: '+e.message,'err')}});
async function autoRefreshFromSaveChange(){if(!autoRefresh||!franchiseLoaded||autoRefreshBusy)return;autoRefreshBusy=true;try{setStatus('Madden AUTOSAVE changed — refreshing sportsbook…','ok');let r=null;let lastErr=null;for(let i=0;i<4;i++){try{r=await window.maddenAPI.reparseFranchise();if(r?.ok)break;lastErr=new Error(r?.error||'Save is still being written.');}catch(e){lastErr=e}await new Promise(x=>setTimeout(x,900));}if(r?.ok){await loadResult(r);setStatus('Autosave detected — sportsbook updated automatically.','ok')}else{throw lastErr||new Error('Unable to refresh the save.')}}catch(e){setStatus('Auto-refresh failed. The Madden save may still be writing; use Refresh Save when ready.','err')}finally{autoRefreshBusy=false}}
window.maddenAPI.onFranchiseSaveChanged(()=>autoRefreshFromSaveChange());
document.getElementById('week').addEventListener('change',()=>{const w=Number(document.getElementById('week').value);document.getElementById('title').textContent=`${phaseLabel(window.selectedPhase||'regular')} • Week ${w}`;renderGames();renderProps()});document.querySelectorAll('#phasebar [data-phase]').forEach(b=>b.addEventListener('click',()=>{window.selectedPhase=b.dataset.phase;populatePhaseWeeks(window.selectedPhase);document.querySelectorAll('#phasebar [data-phase]').forEach(x=>x.classList.toggle('active',x===b));renderGames();renderProps();}));document.getElementById('wager').addEventListener('input',renderSlip);document.getElementById('placeBtn').addEventListener('click',placeBet);document.getElementById('clearSlip').addEventListener('click',()=>{slip=[];saveState();renderSlip()});document.getElementById('copyLog').addEventListener('click',async()=>{const text=document.getElementById('modalText').textContent||'';try{await navigator.clipboard.writeText(text);setStatus('Import log copied to clipboard.','ok')}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();setStatus('Import log copied to clipboard.','ok')}});document.getElementById('closeModal').addEventListener('click',()=>document.getElementById('modal').classList.remove('show'));document.getElementById('closeSlipModal').addEventListener('click',()=>document.getElementById('slipModal').classList.remove('show'));document.getElementById('closeBoxScoreModal').addEventListener('click',()=>document.getElementById('boxScoreModal').classList.remove('show'));document.getElementById('earnBtn').addEventListener('click',()=>showPage('economy'));document.getElementById('closeBalanceModal').addEventListener('click',()=>document.getElementById('balanceModal').classList.remove('show'));document.getElementById('confirmBalanceBtn').addEventListener('click',()=>{const amount=Math.max(0,Number(document.getElementById('balanceAmount').value)||0);if(!amount){setStatus('Enter an amount to add.','err');return}if(!franchiseLoaded){setStatus('Import a Franchise before adding test funds.','err');return}balance+=amount;saveWallet();document.getElementById('balanceModal').classList.remove('show');setStatus(`Added ${money(amount)} to bankroll.`,'ok');renderEconomy()});window.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='0'){e.preventDefault();if(!franchiseLoaded){setStatus('Import a Franchise before using test balance.','err');return}document.getElementById('balanceModalSave').textContent=`Current save: ${currentFranchiseLabel()}`;document.getElementById('balanceModal').classList.add('show');document.getElementById('balanceAmount').focus();document.getElementById('balanceAmount').select()}});document.querySelectorAll('.nav button[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));document.querySelectorAll('[data-nav-toggle]').forEach(b=>b.addEventListener('click',()=>toggleNavGroup(b.dataset.navToggle)));loadNavGroups();loadTheme();initThemeControls();document.body.classList.add('startup-locked');(async()=>{await loadState();renderBalance();renderSlip();renderActiveBets();renderHistory();renderProps();showPage('games');document.body.classList.remove('startup-locked');})();setInterval(()=>{if(activePage==='economy'&&franchiseLoaded)renderEconomy()},1000);
